import { test, expect } from '@playwright/test';

test.describe('Mobile Horizontal Scrolling Disabled', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    await page.goto('/');
  });

  test('should not allow horizontal scrolling on main layout', async ({ page }) => {
    // Get the main layout element
    const mainLayout = page.locator('main, [role="main"], body');

    // Get initial scroll position
    const initialScrollLeft = await page.evaluate(() => window.scrollX);

    // Attempt to scroll horizontally
    await page.evaluate(() => {
      window.scrollBy(100, 0);
    });

    // Verify scroll position hasn't changed
    const finalScrollLeft = await page.evaluate(() => window.scrollX);
    expect(finalScrollLeft).toBe(initialScrollLeft);
  });

  test('should have overflow-x hidden or auto on body element', async ({ page }) => {
    // Check body element overflow-x property
    const bodyOverflowX = await page.evaluate(() => {
      return window.getComputedStyle(document.body).overflowX;
    });

    // Should be either 'hidden' or 'auto' (not 'scroll')
    expect(['hidden', 'auto', 'clip']).toContain(bodyOverflowX);
  });

  test('should prevent horizontal scroll on viewport meta tag', async ({ page }) => {
    // Check if viewport meta tag is properly configured
    const viewportMeta = page.locator('meta[name="viewport"]');
    const viewportContent = await viewportMeta.getAttribute('content');

    // Verify viewport meta tag exists
    expect(viewportContent).toBeTruthy();

    // Verify it contains width=device-width to prevent horizontal scroll
    expect(viewportContent).toContain('width=device-width');
  });

  test('should not have horizontal scrollbar visible', async ({ page }) => {
    // Check if horizontal scrollbar is visible
    const hasHorizontalScroll = await page.evaluate(() => {
      return document.documentElement.scrollWidth > window.innerWidth;
    });

    expect(hasHorizontalScroll).toBe(false);
  });

  test('should maintain layout without horizontal overflow on content elements', async ({ page }) => {
    // Get all main content containers
    const contentElements = page.locator('main, [role="main"], .container, .content');

    // Check each visible element for horizontal overflow
    const elementCount = await contentElements.count();

    for (let i = 0; i < elementCount; i++) {
      const element = contentElements.nth(i);
      const isVisible = await element.isVisible();

      if (isVisible) {
        const hasOverflow = await element.evaluate((el) => {
          return el.scrollWidth > el.clientWidth;
        });

        expect(hasOverflow).toBe(false);
      }
    }
  });

  test('should handle touch swipe without horizontal scroll', async ({ page }) => {
    // Simulate touch swipe gesture
    const mainContent = page.locator('main, [role="main"], body').first();

    // Get initial scroll position
    const initialScroll = await page.evaluate(() => window.scrollX);

    // Simulate swipe by dispatching touch events
    await mainContent.evaluate((el) => {
      const touchStartEvent = new TouchEvent('touchstart', {
        bubbles: true,
        cancelable: true,
        touches: [{ clientX: 300, clientY: 400 } as any],
      });

      const touchEndEvent = new TouchEvent('touchend', {
        bubbles: true,
        cancelable: true,
        changedTouches: [{ clientX: 100, clientY: 400 } as any],
      });

      el.dispatchEvent(touchStartEvent);
      el.dispatchEvent(touchEndEvent);
    });

    // Verify no horizontal scroll occurred
    const finalScroll = await page.evaluate(() => window.scrollX);
    expect(finalScroll).toBe(initialScroll);
  });
});
